import { NextResponse } from "next/server";
import { enqueuePdfJob } from "@/lib/rabbitmq";
import { prisma } from "@/lib/db";
import { FileStatus } from "@prisma/client";

export async function POST(req: Request) {
  try {
    // 1) Body se data lene ki koshish
    let body: any = null;
    try {
      body = await req.json();
    } catch {
      body = null;
    }

    let parsed: any;

    if (body && body.data) {
      // Direct mode: client ne JSON bheja hua hai
      parsed = body.data;
    } else {
      // Fallback: internal /api/pdf-data se lo
      const baseUrl = process.env.APP_URL || "http://localhost:3000";

      const res = await fetch(`${baseUrl}/api/pdf-data`, {
        method: "POST",
        cache: "no-store",
      });

      if (!res.ok) {
        return NextResponse.json(
          { message: "Failed to fetch report data from /api/pdf-data" },
          { status: 500 }
        );
      }

      const json = await res.json();
      if (!json.ok || !json.data) {
        return NextResponse.json(
          { message: "Invalid data from /api/pdf-data" },
          { status: 500 }
        );
      }

      // json = { ok, data }
      // json.data = { status, data }
      parsed = json.data;
    }

    // ---------- YAHAN SE NAYA JSON UNWRAP ----------

    // parsed = { status, data }
    // parsed.data = { data, filteredCount, page, ... }
    // parsed.data.data = { calls, sms, target?, matchedKeywords?, ... }
    const root = parsed as any;          // { status, data }
    const inner = root?.data || {};     // { data, filteredCount, ... }
    const core = inner?.data || {};     // { calls, sms, target?, ... }

    // Ab yahan se arrays lo
    const callRecords: any[] = Array.isArray(core.calls) ? core.calls : [];
    const smsRecords: any[] = Array.isArray(core.sms) ? core.sms : [];

    // DEBUG: count dekhne ke liye
    console.log("DEBUG pdf counts:", callRecords.length, smsRecords.length);

    // Agar target object aata hai to use lo, warna best‑effort se derive karo
    const target: any =
      core.target || {
        code: "N/A",
        targetNumber:
          callRecords[0]?.callerNumber ||
          callRecords[0]?.calleeNumber ||
          "N/A",
        fullName: "Target",
        aliases: [],
        category: [],
        description: "",
        isActive: true,
        riskPriority: "HIGH",
        createdAt: callRecords[0]?.createdAt,
        updatedAt: callRecords[callRecords.length - 1]?.updatedAt,
        fileCount: callRecords.length + smsRecords.length,
        filteredFileCount: callRecords.length + smsRecords.length,
        criticalFileCount: callRecords.filter(
          (c: any) => c.criticality?.[0]?.value === "HIGH"
        ).length,
        filteredCriticalFileCount: callRecords.filter(
          (c: any) => c.criticality?.[0]?.value === "HIGH"
        ).length,
      };

    const matchedKeywords: any = core.matchedKeywords || {};
    const clusteredMarkers: any[] = Array.isArray(core.clusteredMarkers)
      ? core.clusteredMarkers
      : [];
    const targetVocabulary: any[] = Array.isArray(core.targetVocabulary)
      ? core.targetVocabulary
      : [];
    const reportMetadata: any = core.reportMetadata || {};

    // ---------- BAAD KA SARA CODE WAHI (reportPayload, prisma, enqueue) ----------

    const extractEntities = (records: any[], entityType: string): string[] => {
      return Array.from(
        new Set(
          records
            .flatMap((r: any) => {
              const loc = r.callEntities?.Locator as any[] | undefined;
              const entity = loc?.find((l: any) => l.type === entityType);
              return entity?.words || [];
            })
            .map((w: any) => w.value)
        )
      );
    };

    const getThreatLevel = (criticality: string): string => {
      return criticality === "HIGH"
        ? "🔴 CRITICAL"
        : criticality === "MEDIUM"
        ? "🟠 MODERATE"
        : "🟢 LOW";
    };

    const reportPayload = {
      title: `Intelligence Report - ${target.fullName || "Target"} (${
        target.targetNumber || "N/A"
      })`,

      coverPage: {
        classification: reportMetadata.classification || "CONFIDENTIAL",
        generatedAt: new Date().toLocaleString("en-IN"),
        reportId: reportMetadata.reportId || `RPT-${Date.now()}`,
        analyst: reportMetadata.analyst || "System Generated",
      },

      targetInfo: {
        code: target.code || "N/A",
        number: target.targetNumber || "N/A",
        name: target.fullName || "N/A",
        aliases: Array.isArray(target.aliases)
          ? target.aliases.join(", ")
          : "N/A",
        categories: Array.isArray(target.category)
          ? target.category.join(", ")
          : "N/A",
        description: target.description || "No description",
        status: target.isActive ? "🔴 ACTIVE" : "🟢 INACTIVE",
        riskPriority:
          target.riskPriority || getThreatLevel(target.riskLevel || "LOW"),
        createdAt: target.createdAt
          ? new Date(target.createdAt).toLocaleDateString()
          : "N/A",
        updatedAt: target.updatedAt
          ? new Date(target.updatedAt).toLocaleDateString()
          : "N/A",
      },

      userDetails: target.userDetails || {
        email: "N/A",
        phone: "N/A",
        address: target.address || "N/A",
        city: "N/A",
        state: "N/A",
        country: "N/A",
      },

      organizations: Array.isArray(target.organisations)
        ? target.organisations.map((org: any) => ({
            name: org.name || org,
            role: org.role || "Associated",
            riskLevel: org.riskLevel || "UNKNOWN",
          }))
        : [],

      stats: {
        totalCalls: callRecords.length,
        totalSMS: smsRecords.length,
        totalRecords: callRecords.length + smsRecords.length,
        highPriorityCalls: callRecords.filter(
          (c: any) => c.criticality?.[0]?.value === "HIGH"
        ).length,
        mediumPriorityCalls: callRecords.filter(
          (c: any) => c.criticality?.[0]?.value === "MEDIUM"
        ).length,
        lowPriorityCalls: callRecords.filter(
          (c: any) => c.criticality?.[0]?.value === "LOW"
        ).length,
        highPrioritySMS: smsRecords.filter(
          (s: any) => s.criticality?.[0]?.value === "HIGH"
        ).length,
        fileCount: target.fileCount || callRecords.length + smsRecords.length,
        filteredFileCount: target.filteredFileCount || 0,
        criticalFiles: target.criticalFileCount || 0,
        filteredCriticalFileCount: target.filteredCriticalFileCount || 0,
        callCount: callRecords.length,
        smsCount: smsRecords.length,
        criticalCallCount: callRecords.filter(
          (c: any) => c.criticality?.[0]?.value === "HIGH"
        ).length,
        criticalSMSCount: smsRecords.filter(
          (s: any) => s.criticality?.[0]?.value === "HIGH"
        ).length,
        generatedAt: new Date().toISOString(),
      },

      callRecordsDetailedTable: {
        headers: [
          "DateTime",
          "Duration",
          "Caller",
          "Callee",
          "Type",
          "Category",
          "Priority",
          "Status",
          "Language",
          "Location",
          "File",
        ],
        rows: callRecords.map((c: any) => [
          c.callDatetime
            ? new Date(c.callDatetime).toLocaleString("en-IN")
            : "N/A",
          c.duration ? `${c.duration}s` : "N/A",
          c.callerNumber || "N/A",
          c.calleeNumber || "N/A",
          c.callType?.[0]?.value || "N/A",
          Array.isArray(c.category)
            ? c.category.map((x: any) => x.value || x).join(", ")
            : "General",
          c.criticality?.[0]?.value || "N/A",
          c.callReadStatus ? "✓ Read" : "Unread",
          c.language || "N/A",
          c.startLocation
            ? `${c.startLocation.latitude}, ${c.startLocation.longitude}`
            : "N/A",
          c.fileName || "N/A",
        ]),
      },

      smsRecordsDetailedTable: {
        headers: [
          "DateTime",
          "From",
          "Type",
          "Category",
          "Priority",
          "Message",
          "Status",
          "File",
        ],
        rows: smsRecords.map((s: any) => [
          s.smsDatetime
            ? new Date(s.smsDatetime).toLocaleString("en-IN")
            : "N/A",
          s.senderNumber || "Unknown",
          s.smsType?.[0]?.value || "N/A",
          Array.isArray(s.category)
            ? s.category.map((x: any) => x.value || x).join(", ")
            : "General",
          s.criticality?.[0]?.value || "N/A",
          (s.message || "N/A").substring(0, 100),
          s.smsReadStatus ? "✓ Read" : "Unread",
          s.fileName || "N/A",
        ]),
      },

      topCallsSummaries: callRecords.slice(0, 10).map((c: any, idx: number) => ({
        index: idx + 1,
        time: c.callDatetime
          ? new Date(c.callDatetime).toLocaleString("en-IN")
          : "N/A",
        from: c.callerNumber || "N/A",
        to: c.calleeNumber || "N/A",
        duration: c.duration ? `${c.duration}s` : "N/A",
        priority: c.criticality?.[0]?.value || "N/A",
        category: Array.isArray(c.category)
          ? c.category.map((x: any) => x.value || x).join(", ")
          : "N/A",
        summary: c.summary || "No summary available",
        speakers:
          Array.isArray(c.speakers) && c.speakers.length > 0
            ? c.speakers.join(", ")
            : "N/A",
        comments:
          Array.isArray(c.comments) && c.comments.length > 0
            ? c.comments
                .map((cm: any) => cm.content || cm.text || cm)
                .join("; ")
            : "N/A",
      })),

      entities: {
        persons: extractEntities(callRecords, "PERSON"),
        locations: extractEntities(callRecords, "LOCATION"),
        organizations: extractEntities(callRecords, "ORGANIZATION"),
        phoneNumbers: Array.from(
          new Set(
            callRecords
              .map((c: any) => [c.callerNumber, c.calleeNumber])
              .flat()
              .filter(Boolean)
          )
        ),
      },

      geographicData: {
        clusteredLocations: clusteredMarkers.map((marker: any) => ({
          cluster: marker.cluster || "N/A",
          latitude: marker.position?.[0] || marker.latitude || "N/A",
          longitude: marker.position?.[1] || marker.longitude || "N/A",
          count: marker.count || 0,
          description: marker.description || "Cluster point",
        })),
        callLocations: callRecords
          .filter((c: any) => c.startLocation?.latitude)
          .map((c: any) => ({
            datetime: c.callDatetime
              ? new Date(c.callDatetime).toLocaleString("en-IN")
              : "N/A",
            latitude: c.startLocation.latitude,
            longitude: c.startLocation.longitude,
            caller: c.callerNumber,
            callee: c.calleeNumber,
          })),
      },

      keywordsSummary: {
        targetKeywords: (matchedKeywords.matchedTargetKeywords || [])
          .slice(0, 20)
          .map((k: any) => ({
            keyword: k.keyword || "N/A",
            label: k.label || "N/A",
            callCount: k.callCount || 0,
            smsCount: k.smsCount || 0,
            totalCount: k.totalCount || 0,
            threat: getThreatLevel(k.label || "LOW"),
          })),
        globalKeywords: (matchedKeywords.matchedGlobalKeywords || [])
          .slice(0, 20)
          .map((k: any) => ({
            keyword: k.keyword || "N/A",
            label: k.label || "N/A",
            callCount: k.callCount || 0,
            smsCount: k.smsCount || 0,
            totalCount: k.totalCount || 0,
            threat: getThreatLevel(k.label || "LOW"),
          })),
      },

      vocabularyAnalysis: targetVocabulary.slice(0, 30).map((v: any) => ({
        word: v.phrase || v.word || v,
        frequency: v.totalCount || v.frequency || v.count || 1,
        context: "General",
        language: v.language || "Unknown",
        sentiment: v.label || "Neutral",
      })),

      threatAssessment: {
        overallThreat:
          target.riskPriority ||
          getThreatLevel(
            callRecords.some(
              (c: any) => c.criticality?.[0]?.value === "HIGH"
            )
              ? "HIGH"
              : "MEDIUM"
          ),
        threatFactors: [
          {
            factor: "High Priority Communications",
            count: callRecords.filter(
              (c: any) => c.criticality?.[0]?.value === "HIGH"
            ).length,
            severity: "HIGH",
          },
          {
            factor: "Suspicious Keywords Detected",
            count: (matchedKeywords.matchedGlobalKeywords || []).filter(
              (k: any) => k.label === "HIGH"
            ).length,
            severity: "HIGH",
          },
          {
            factor: "Geographic Movement",
            count: clusteredMarkers.length,
            severity: "MEDIUM",
          },
          {
            factor: "Associated Organizations",
            count: (target.organisations || []).length,
            severity: "MEDIUM",
          },
          {
            factor: "Contact Network Size",
            count: Array.from(
              new Set(
                callRecords
                  .map((c: any) => [c.callerNumber, c.calleeNumber])
                  .flat()
                  .filter(Boolean)
              )
            ).length,
            severity: target.riskLevel === "HIGH" ? "HIGH" : "MEDIUM",
          },
        ],
        recommendations: [
          "Continuous monitoring recommended",
          "Cross-reference with known associates",
          "Geographic tracking in priority areas",
          "Keyword alert optimization needed",
          "Network analysis expansion suggested",
        ],
      },

      rawJson: JSON.stringify(parsed, null, 2),

      summary: {
        reportTitle: `Intelligence Report - ${target.fullName || "Target"}`,
        targetNumber: target.targetNumber,
        targetCode: target.code,
        generatedDate: new Date().toLocaleString("en-IN"),
        totalPages: 25,
        dataPoints: {
          calls: callRecords.length,
          sms: smsRecords.length,
          uniqueContacts: Array.from(
            new Set(
              callRecords
                .map((c: any) => [c.callerNumber, c.calleeNumber])
                .flat()
                .filter(Boolean)
            )
          ).length,
          locations: clusteredMarkers.length,
          keywords: (matchedKeywords.matchedGlobalKeywords || []).length,
        },
      },
    };

    // 3) File record create karo
    const fileRecord = await prisma.file.create({
      data: {
        fileName: `intelligence-report-${Date.now()}.pdf`,
        status: FileStatus.queued,
        requestBy: "system",
        downloadUrl: "",
      },
    });

    // 4) RabbitMQ me job daalo
    await enqueuePdfJob({ id: fileRecord.id, payload: reportPayload });

    return NextResponse.json(
      {
        fileId: fileRecord.id,
        status: fileRecord.status,
        message: "PDF generation queued",
      },
      { status: 202 }
    );
  } catch (err) {
    console.error("❌ /api/pdf error:", err);
    return NextResponse.json(
      { message: "Internal server error" },
      { status: 500 }
    );
  }
}
